DISTINCT tpd.TRADE_ID
FROM TRD_PRODUCT_DEAL tpd
INNER JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.TRADE_ID = tpda.TRADE_ID
INNER JOIN SETTLE_TRANS_TG_MAPPING sttm ON tpd.TRADE_ID = sttm.TRADE_ID_TG
LEFT JOIN SETTLE_TRANS_DATA_STATUS D ON D.TRADE_ID = sttm.TRADE_ID

    tpd.TRADE_STATUS = #{TRADE_STATUS_01}
